import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

import java.io.*;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class XXEUtil {

    public static String extractXml(InputStream xmlStream) throws IOException {
        // 使用 JSoup 解析 XML 文件并提取数据
        Document document = Jsoup.parse(xmlStream, "UTF-8");
        return document.body().text();
    }

    public static void extractZip(InputStream zipStream, File destDir) throws IOException {
        try (ZipInputStream zipInputStream = new ZipInputStream(zipStream)) {
            ZipEntry entry;
            while ((entry = zipInputStream.getNextEntry()) != null) {
                // 提取 ZIP 文件中的内容
                if (!entry.isDirectory()) {
                    File outputFile = new File(destDir, entry.getName());
                    writeBytes(zipInputStream, outputFile);
                }
            }
        }
    }

    private static void writeBytes(InputStream in, File file) throws IOException {
        try (BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(file))) {
            byte[] buffer = new byte[1024];
            int len;
            while ((len = in.read(buffer)) != -1) {
                bos.write(buffer, 0, len);
            }
        }
    }
}
```

