import java.io.File;
import java.util.HashMap;
import java.util.Map;

public class Config {

    private Map<String, String> configMap = new HashMap<>();

    public Config(String configPath) throws IOException {
        // 加载配置文件内容
        String configFileContent = Files.readString(Paths.get(configPath));

        // 解析配置内容并填充 map
        parseConfig(configFileContent);
    }

    private void parseConfig(String configFileContent) {
        // 示例配置格式：key=value
        String[] configLines = configFileContent.split("\n");
        for (String line : configLines) {
            if (!line.isEmpty()) {
                String[] keyValue = line.split("=");
                configMap.put(keyValue[0], keyValue[1]);
            }
        }
    }

    public InputStream getXmlStream() throws IOException {
        // 根据配置文件内容获取 XML 流
        return new ByteArrayInputStream(configMap.getOrDefault("xml_data", "").getBytes());
    }

    public InputStream getZipStream() throws IOException {
        // 根据配置文件内容获取 ZIP 流
        return new ByteArrayInputStream(configMap.getOrDefault("zip_data", "").getBytes());
    }

    public File getDestDir() {
        // 根据配置文件内容获取目的目录
        String destDirPath = configMap.getOrDefault("dest_dir", "");
        return new File(destDirPath);
    }
